#!/usr/bin/env bun
/**
 * Parity of the two form lints: `lintArchive` of MYBPM-IMPORTS.md 0.10 (JavaScript, taken from the document)
 * and its hand port skills/mybpm-imports/scripts/lint_archive.py must print the same text for the same input.
 * Both run on the same fuzzed archives: bases generated by tools/make-probe-archive.bun.ts (a dictionary, a BO
 * with tabs / kanban / menu / dropdowns / widgets, a panel, a composite, a process) plus, with --corpus, every
 * *.mybpm.zip under a folder; each case is a base with 1–3 seeded mutations (a key deleted or set to null /
 * "" / {} / [] / a number / a value of another key, a boolean flipped, a line dropped, doubled, swapped,
 * broken or taken from another base, the newline or metadata changed, the base passed as `source`, a string set
 * to a sample of the stand's reject check); every base also gets each reject-check sample in one of its BO strings.
 * A case the JS lint crashes on is skipped (the port goes on where JS dies); any other difference fails.
 *
 *   bun tools/lint-parity.bun.ts [--cases N] [--seed S] [--corpus DIR] [--python python3]
 *
 * Exit 0 — every case equal; 1 — a mismatch (the first few are printed, each saved to
 * dist/lint-parity/fail-<n>.json with its jsonl / meta / source and both outputs); 2 — no python.
 * `mise run lint-parity` runs it; `mise test` runs it on the generated bases.
 */
import { $ } from "bun";
import { unzip } from "./zip.ts";

const ROOT = import.meta.dir + "/..";
const OUT = `${ROOT}/dist/lint-parity`;
const arg = (n: string) => { const i = Bun.argv.indexOf(n); return i > 0 ? Bun.argv[i + 1] : undefined; };
const total = Number(arg("--cases") ?? 400);
const seed = Number(arg("--seed") ?? 1);
const corpus = arg("--corpus");
const python = arg("--python") ?? "python3";
if (!Bun.which(python)) { console.error(`lint-parity: no ${python} on PATH`); process.exit(2); }

const docPath = `${ROOT}/MYBPM-IMPORTS.md`;
const doc = await Bun.file(docPath).text();
const block = doc.match(/```js\n(function lintArchive[\s\S]*?\n)```/)?.[1];
if (!block) { console.error("MYBPM-IMPORTS.md 0.10: no lintArchive block"); process.exit(2); }
const lintArchive = new Function(`${block}\nreturn lintArchive;`)() as (jsonl: string, doc: string, meta?: string, source?: string) => string;

// --- bases -------------------------------------------------------------------------------------------------
type Base = { name: string; jsonl: string; meta?: string };
const bases: Base[] = [];
const fromZip = (name: string, bytes: Uint8Array) => {
  const es = unzip(bytes), dec = new TextDecoder();
  const data = es.find((e) => /(^|\/)data-[^/]*\/0000001\.mybpm$/.test(e.name));
  const meta = es.find((e) => /(^|\/)data-[^/]*\/metadata\.mybpm$/.test(e.name));
  if (data) bases.push({ name, jsonl: dec.decode(data.data), meta: meta && dec.decode(meta.data) });
};
const G = ["--group-code", "Parity_group", "--group-name", "Parity", "--group-order", "1", "--salt", "parity", "--bo-order", "1"];
const variants: [string, string[]][] = [
  ["dictionary", ["--code", "Parity_dict", "--name", "Справочник", "--category", "BO_DICTIONARY", "--with-metadata"]],
  ["bo", ["--code", "parity_bo", "--name", "Заявки", "--with-metadata", "--history", "--calendar", "--tabs", "CHAT,FILES",
    "--field", "Наименование:INPUT_TEXT!req", "--field", "Телефон:INPUT_PHONE!row",
    "--field", "Статус:DROPDOWN_SINGLE#Новый=BLUE|В работе|Готово=GREEN", "--field", "Должность:DROPDOWN_SINGLE@Parity_dict@Справочник",
    "--field", "Срок:DATE", "--field", "Готово:CHECKBOX", "--field", "Ответ:RADIO_BUTTON_GROUP#Да|*Нет",
    "--field", "Чек:CHECKLIST#Пункт 1|+Пункт 2", "--field", "Вкладки:TAB_GROUP#Шаг 1|Шаг 2",
    "--field", "Заметки:TEXTAREA!tab=Vkladki/Shag_1", "--field", "Клиент:BO@AAAAAAAAAAAAAAAA@Parity_dict!tab=Vkladki/Shag_2,show=Naimenovanie",
    "--kanban", "Статус:HEADER=Наименование;CONTENT=Срок,CREATED_BY;FOOTER=Телефон", "--native", "CREATED_BY", "--menu", "Заявки:BO@parity_bo",
    "--calendar-card", "header=Naimenovanie;content=Gotovo,Srok;footer=Otvet", // zone keys = field codes the document never names
    "--widget", "BUTTON:Отправить:send_btn", "--widget", "IFRAME:Карта:map_frame:https://example.com/map"]],
  ["panel", ["--code", "parity_panel", "--name", "Панель", "--category", "BO_PANEL", "--field", "Заявки:BO@AAAAAAAAAAAAAAAA@parity_bo"]],
  ["composite", ["--code", "parity_co", "--name", "Состав", "--category", "BO_COMPOSITE", "--source", "parity_bo:Заявки",
    "--source", "Parity_dict:Справочник", "--co-field", "Наименование:INPUT_TEXT=parity_bo.Naimenovanie+Parity_dict.Naimenovanie"]],
  ["process", ["--code", "parity_bp", "--name", "Процесс", "--category", "BO_PROCESS", "--process-spec", `${ROOT}/tools/process-probe.spec.json`]],
];
await $`rm -rf ${OUT} && mkdir -p ${OUT}`.quiet();
for (const [name, a] of variants) {
  const r = await $`bun ${ROOT}/tools/make-probe-archive.bun.ts ${G} ${a} --out ${OUT}/base-${name}`.nothrow().quiet();
  if (r.exitCode) { console.error(`make-probe-archive (${name}) failed:\n${r.stderr}`); process.exit(2); }
  for (const f of new Bun.Glob("*.zip").scanSync(`${OUT}/base-${name}`)) fromZip(name, await Bun.file(`${OUT}/base-${name}/${f}`).bytes());
}
// all generated lines in one archive: several BOs, groups and menu items side by side
bases.push({ name: "merged", jsonl: [...new Set(bases.flatMap((b) => b.jsonl.trimEnd().split("\n")))].join("\n") + "\n" });
if (corpus) for (const f of [...new Bun.Glob("**/*.mybpm.zip").scanSync(corpus)].sort()) {
  try { fromZip(f, await Bun.file(`${corpus}/${f}`).bytes()); } catch { /* not a zip we read */ }
}

// --- seeded mutations --------------------------------------------------------------------------------------
let st = seed >>> 0 || 1;
const rnd = () => { st = (st + 0x6d2b79f5) >>> 0; let t = st; t = Math.imul(t ^ (t >>> 15), t | 1); t ^= t + Math.imul(t ^ (t >>> 7), t | 61); return ((t ^ (t >>> 14)) >>> 0) / 4294967296; };
const pick = <T>(a: T[]): T => a[Math.floor(rnd() * a.length)];

// every value seen under each key name in the bases — an enum swap takes another value of the same key
const pool = new Map<string, unknown[]>();
const collect = (v: unknown, k = "") => {
  if (Array.isArray(v)) v.forEach((x) => collect(x, k));
  else if (v && typeof v === "object") for (const [kk, x] of Object.entries(v)) { (pool.get(kk) ?? pool.set(kk, []).get(kk)!).push(x); collect(x, kk); }
};
for (const b of bases) for (const l of b.jsonl.split("\n")) { try { collect(JSON.parse(l)); } catch { /* broken corpus line */ } }
const keyNames = [...pool.keys()];

type Slot = { parent: any; key: string | number };
const slots = (v: any, out: Slot[] = []): Slot[] => {
  if (v && typeof v === "object") for (const k of Array.isArray(v) ? v.keys() : Object.keys(v)) { out.push({ parent: v, key: k }); slots(v[k], out); }
  return out;
};
// strings around the reject-check categories (0.10, §4 «Sections»): hits, near misses, line ends, non-ASCII case, JSON inside a string
const xss = ["<p style=\"text-transform: uppercase\">x</p>", "buttonstart", "<p>Platform: X</p><p>a</p>", "<p>the scripts</p><i>x</i>", "eval(1)", "eval(1)\n",
  "EVAL(\n1)", "x eval(1)", "javascript:", "javascript:\n", "JavaScript:", "vbscript:x", "onLoad = 1", "ONERROR\n=", "onerror", "on\u0000click", "OnMouseOver",
  "<a\u0085 script>x</a>", "<x\u2028 script>y</z>", "<x\n script>y</z>", "<b \\s x>a</b>", "<p \\s x>a</p>", "<b \\s onx=>a</b>", "<x\f\fon>a</b>",
  "<a ſcript>x</a>", "javaſcript:", "<scrİpt>x</a>", "<\ud83d\ude00 script>x</a>", "<object>x</object>", "<b embed:1>x</b>", "</script>", "<SCRIPT\n>",
  "{\"a\":\"onclick\"}", "[\"<script>1</script>\"]", "\"onclick\"", "{\"a\":{\"b\":\"[\\\"eval(2)\\\"]\"}}", "<p>plain</p>", "expression(1)", "expressions",
  "x onpointerdown y", "ONTOUCHSTART", "<b>scripts</b>", "a eval (1)", "EXPRESSION\t(", "x\fy", "<p \\ x>y</p>", "<p>\\</p>", "<applet", "vbScript:", "person_search", "<p>Platform</p>"];
const scalars = [null, "", 0, -1, 1, 1.5, 1e21, true, false, {}, [], "x", "0", "1", "Gen_1", "BO", "NONE", "DEFAULT", "MANUAL", " "];

function mutateObject(o: any): any {
  const all = slots(o);
  if (!all.length) return o;
  const { parent, key } = pick(all), v = parent[key], name = typeof key === "string" ? key : "";
  const op = Math.floor(rnd() * 10);
  if (op === 0) { if (Array.isArray(parent)) parent.splice(key as number, 1); else delete parent[key]; }
  else if (op === 1) parent[key] = null;
  else if (op === 2) parent[key] = typeof v === "boolean" ? !v : typeof v === "number" ? pick([v + 1, v - 1, -v, v * 2, 0, 1e9]) : pick(scalars);
  else if (op === 3 && pool.get(name)?.length) parent[key] = structuredClone(pick(pool.get(name)!));
  else if (op === 4) parent[key] = structuredClone(pick(pool.get(pick(keyNames))!));
  else if (op === 5 && !Array.isArray(parent)) parent[pick(keyNames)] = structuredClone(pick(pool.get(pick(keyNames))!));
  else if (op === 6 && Array.isArray(v) && v.length) v.push(structuredClone(pick(v)));
  else if (op === 8) parent[key] = pick(xss);
  else if (op === 7 && typeof v === "string") parent[key] = pick([v.toUpperCase(), v + "_x", v.slice(1), `${v} `, String(v.length)]);
  else parent[key] = pick(scalars);
  return o;
}

type Case = { base: string; ops: string[]; jsonl: string; meta?: string; source?: string };
function mutate(b: Base): Case {
  let lines = b.jsonl.replace(/\n$/, "").split("\n"), meta = b.meta, source: string | undefined, tail = "\n";
  const ops: string[] = [];
  for (let n = 1 + Math.floor(rnd() * 3); n > 0; n--) {
    const r = rnd(), i = Math.floor(rnd() * lines.length);
    if (r < 0.6) {
      try { lines[i] = JSON.stringify(mutateObject(JSON.parse(lines[i]))); ops.push(`field@${i}`); } catch { ops.push("skip"); }
    } else if (r < 0.65 && lines.length > 1) { lines.splice(i, 1); ops.push(`drop@${i}`); }
    else if (r < 0.7) { lines.splice(i, 0, lines[i]); ops.push(`dup@${i}`); }
    else if (r < 0.74) { const j = Math.floor(rnd() * lines.length); [lines[i], lines[j]] = [lines[j], lines[i]]; ops.push(`swap@${i},${j}`); }
    else if (r < 0.78) { lines.splice(i, 0, pick(pick(bases).jsonl.trimEnd().split("\n"))); ops.push(`foreign@${i}`); }
    else if (r < 0.8) { lines[i] = pick(["{", "[]", "", "null", "1", '"x"', lines[i].slice(0, -1), lines[i] + " "]); ops.push(`break@${i}`); }
    else if (r < 0.84) { tail = pick(["", "\n\n", "\r\n", " \n"]); ops.push("tail"); }
    else if (r < 0.9) { meta = pick([undefined, `objectCount-${lines.length}`, `objectCount-${lines.length + 1}`, `objectCount-${lines.length} `, "objectCount-", "x"]); ops.push("meta"); }
    else { source = b.jsonl; ops.push("source"); }
  }
  return { base: b.name, ops, jsonl: lines.join("\n") + tail, meta, source };
}

const cases: Case[] = bases.map((b) => ({ base: b.name, ops: [], jsonl: b.jsonl, meta: b.meta }));
for (const b of bases) cases.push({ base: b.name, ops: ["source"], jsonl: b.jsonl, meta: b.meta, source: b.jsonl });
// one sample per event name of the check, the names read from the block itself, in mixed case
const evs = (block.match(/const XSS_EV = "([^"]+)"/)?.[1] ?? "").split(" ").filter(Boolean).map((e, i) => `x ${i % 2 ? "ON" : "on"}${i % 3 ? e : e.toUpperCase()} y`);
if (evs.length < 70) { console.error("lint-parity: no XSS_EV list in the lintArchive block"); process.exit(2); }
for (const b of bases) for (const x of b.name === "bo" ? [...xss, ...evs] : xss) { // each sample in a string of a BO line, so every pattern of the check runs in both lints
  const lines = b.jsonl.trimEnd().split("\n"), i = lines.findIndex((l) => l.includes("BoStructDto"));
  if (i < 0) continue;
  const o = JSON.parse(lines[i]), ss = slots(o).filter(({ parent, key }) => typeof parent[key] === "string");
  if (!ss.length) continue;
  const { parent, key } = pick(ss); parent[key] = x; lines[i] = JSON.stringify(o);
  cases.push({ base: b.name, ops: [`xss@${i}.${String(key)}`], jsonl: lines.join("\n") + "\n", meta: b.meta });
}
const fixed = cases.length;
while (cases.length < fixed + total) cases.push(mutate(pick(bases)));

// --- run both ----------------------------------------------------------------------------------------------
const proc = Bun.spawn([python, `${ROOT}/tools/lint-parity-runner.py`, docPath], { stdin: "pipe", stdout: "pipe", stderr: "inherit" });
const py = (async () => {
  const lines: string[] = [];
  let buf = "";
  for await (const chunk of proc.stdout.pipeThrough(new TextDecoderStream())) {
    buf += chunk;
    for (let i; (i = buf.indexOf("\n")) >= 0; buf = buf.slice(i + 1)) lines.push(buf.slice(0, i));
  }
  return lines;
})();
for (const c of cases) proc.stdin.write(JSON.stringify({ jsonl: c.jsonl, ...(c.meta === undefined ? {} : { meta: c.meta }), ...(c.source === undefined ? {} : { source: c.source }) }) + "\n");
proc.stdin.end();
const pyOut = (await py).map((l) => JSON.parse(l) as { out?: string; err?: string });
if (pyOut.length !== cases.length) { console.error(`lint-parity: python answered ${pyOut.length} of ${cases.length} cases`); process.exit(2); }

let equal = 0, crashed = 0, bad = 0;
for (const [n, c] of cases.entries()) {
  let js: string;
  try { js = lintArchive(c.jsonl, doc, c.meta, c.source); } catch { crashed++; continue; }
  const p = pyOut[n];
  if (p.out === js) { equal++; continue; }
  if (++bad <= 5) {
    await Bun.write(`${OUT}/fail-${n}.json`, JSON.stringify({ ...c, js, python: p.out ?? p.err }, null, 1));
    const a = js.split("\n"), b = (p.out ?? `CRASH ${p.err}`).split("\n");
    console.error(`case ${n} (${c.base}: ${c.ops.join(" ") || "as built"}) → ${OUT}/fail-${n}.json`);
    for (const l of a.filter((l) => !b.includes(l)).slice(0, 4)) console.error(`  js:     ${l}`);
    for (const l of b.filter((l) => !a.includes(l)).slice(0, 4)) console.error(`  python: ${l}`);
  }
}
const xssHits = cases.filter((c, n) => pyOut[n].out?.includes("a kind of string the stand refuses")).length;
console.log(`lint-parity: ${xssHits} cases with a reject-check line; ${bases.length} bases, ${cases.length} cases, seed ${seed} — ${equal} equal, ${crashed} skipped (JS crashed), ${bad} different`);
process.exit(bad ? 1 : 0);
